/**
 * The published artwork manifest (public/isometric-art/manifest.json,
 * generated by scripts/build-isometric-art.ts) as the admin artwork routes
 * see it: the subjects, the curated baseline associations and the hotspots.
 *
 * Loaded through the same ASSETS fetcher as the base dataset (the manifest
 * ships in the same deployment as the server), validated with the shared
 * schema and cached per isolate keyed by the manifest's `generatedFrom`
 * hashes. A failure is never cached and is reported as 'unavailable' (503):
 * the owner can never verify against a manifest the server cannot read.
 * Read-only: the manifest and the originals are never written.
 */
import { isometricArtManifestSchema, type IsometricArtManifest } from '../src/isometric-art/schema.ts';
import { DomainError } from './errors.ts';

export type FetchAsset = (path: string) => Promise<Response>;

/** Path of the manifest inside the static deployment. */
export const ARTWORK_MANIFEST_PATH = 'isometric-art/manifest.json';

const unavailable = (message: string, cause?: unknown) =>
  new DomainError(
    'unavailable',
    `Artwork manifest unavailable: ${message}`,
    cause === undefined ? {} : { cause },
  );

let cached: { key: string; manifest: IsometricArtManifest } | null = null;

/** Drops the per-isolate cache (tests). */
export function clearArtworkManifestCache(): void {
  cached = null;
}

const cacheKey = (raw: unknown): string | null => {
  if (typeof raw !== 'object' || raw === null) return null;
  const g = (raw as { generatedFrom?: unknown }).generatedFrom;
  if (typeof g !== 'object' || g === null) return null;
  const { registrySha256, inventorySha256, hotspotsSha256 } = g as Record<string, unknown>;
  return [registrySha256, inventorySha256, hotspotsSha256].every((s) => typeof s === 'string')
    ? `${String(registrySha256)}:${String(inventorySha256)}:${String(hotspotsSha256)}`
    : null;
};

export async function loadArtworkManifest(fetchAsset: FetchAsset): Promise<IsometricArtManifest> {
  let res: Response;
  try {
    res = await fetchAsset(ARTWORK_MANIFEST_PATH);
  } catch (cause) {
    throw unavailable('it could not be read.', cause);
  }
  if (!res.ok) throw unavailable(`it returned HTTP ${res.status}.`);
  let raw: unknown;
  try {
    raw = await res.json();
  } catch (cause) {
    throw unavailable('it is not valid JSON.', cause);
  }
  const key = cacheKey(raw);
  if (key !== null && cached?.key === key) return cached.manifest;
  const parsed = isometricArtManifestSchema.safeParse(raw);
  if (!parsed.success) throw unavailable('it failed validation.');
  if (key !== null) cached = { key, manifest: parsed.data };
  return parsed.data;
}
